 1 | import axios from 'axios';
 2 | import { message } from 'antd';
 3 | import { trackRequest } from 'raven';
 4 | import { login } from '@/utils';
 5 | import { PERMISSION_TIPS_WHITE_LIST } from '@/constants/whiteList';
 6 | import deepCleanParams from '@/utils/deepCleanParams';
 7 | 
 8 | function getBaseUrl() {
 9 |   const prefix = (window as any).REACT_APP_GLOBAL_HOTEL_API_PREFIX || '';
10 |   return `${prefix}`;
11 | }
12 | export const HOTEL_FILE_UPLOAD =
13 |   getBaseUrl() + '/ota/hotel/inner/mis/circle/uploadHotelsByFile';
14 | export const HOTEL_IMG_UPLOAD =
15 |   getBaseUrl() + '/ota/hotel/inner/mis/perk/uploadPicture';
16 | 
17 | const service = axios.create({
18 |   baseURL: getBaseUrl() + '/ota/hotel',
19 |   timeout: 30000,
20 |   headers: {
21 |     'Content-Type': 'application/json',
22 |   },
23 | });
24 | 
25 | service.interceptors.request.use(
26 |   (config: any) => {
27 |     if (config.params) {
28 |       config.params = deepCleanParams(config.params);
29 |     }
30 |     if (config.data) {
31 |       config.data = deepCleanParams(config.data);
32 |     }
33 |     return config;
34 |   },
35 |   (error: any) => {
36 |     return Promise.reject(error);
37 |   }
38 | );
39 | 
40 | service.interceptors.response.use(
41 |   (response): any => {
42 |     trackRequest(response);
43 | 
44 |     const { code, data, errno } = response.data;
45 | 
46 |     if (errno === 403) {
47 |       window.location = data.redirectUrl;
48 |       message.error('登录超时，请重新登录');
49 |       return;
50 |     }
51 | 
52 |     if ((errno && errno === 401) || (code && code === 401)) {
53 |       login();
54 |     }
55 | 
56 |     if ((errno && errno !== 0) || (code && code !== 0)) {
57 |       message.error(response.data.errmsg || response.data.msg);
58 |       return Promise.reject(response.data);
59 |     }
60 |     return Promise.resolve(response.data);
61 |   },
62 |   (error) => {
63 |     if (error.response.status === 403) {
64 |       const baseUrl = error?.config?.baseURL || '';
65 |       const url = error?.config?.url || '';
66 |       const path = url.replace(baseUrl, '');
67 |       // 不在白名单内的才提示
68 |       const needTips = !PERMISSION_TIPS_WHITE_LIST.includes(path);
69 |       needTips &&
70 |         message.error({
71 |           content: '无权限，点击前往申请',
72 |           onClick: () => {
73 |             window.location.href = process.env.REACT_APP_UPM_APPLY_URL!;
74 |           },
75 |         });
76 |     } else {
77 |       message.error(error.response.status + ': ' + error.response.statusText);
78 |     }
79 |     trackRequest(error);
80 |     return Promise.reject(error);
81 |   }
82 | );
83 | 
84 | export function setBaseUrl() {
85 |   service.defaults.baseURL = getBaseUrl();
86 | }
87 | 
88 | export default service;
89 |

