  8 | 
  9 | /** 使用 zod schema 验证数据结构是否正确 */
 10 | export function validateData<T = unknown>(
 11 |   schema: z.ZodSchema<T>,
 12 |   data: unknown
 13 | ): T | null {
 14 |   const res = schema.safeParse(data);
 15 |   if (res.success) {
 16 |     return res.data;
 17 |   } else {
 18 |     console.error(
 19 |       ` ================== schema parse error ================= `,
 20 |       res.error
 21 |     );
 22 |     return null;
 23 |   }
 24 | }
 25 | 
 26 | /** 获取分页入参 zod 对象 */
 27 | export function getListParamSchema(): typeof zodPaginationParam;
 28 | export function getListParamSchema<T extends z.AnyZodObject>(
 29 |   data: T
 30 | ): z.ZodObject<
 31 |   z.infer<typeof zodPaginationParam> & z.infer<T>,
 32 |   'strip',
 33 |   z.ZodTypeAny,
 34 |   z.infer<typeof zodPaginationParam> & z.infer<T>
 35 | >;
 36 | export function getListParamSchema<T extends z.AnyZodObject>(data?: T) {
 37 |   if (data) {
 38 |     return zodPaginationParam.extend(data.shape);
 39 |   }
 40 |   return zodPaginationParam;
 41 | }
 42 | 
 43 | /** 获取响应 zod 对象 */
 44 | export function getResSchema<T extends z.ZodTypeAny>(data: T) {
 45 |   return z.object({
 46 |     code: z.number(),
 47 |     data,
 48 |     msg: z.string(),
 49 |     trace_id: z.string(),
 50 |   });
 51 | }
 52 | 
 53 | /** 获取响应列表 zod 对象 */
 54 | export function getResListSchema<T extends z.ZodTypeAny>(data: T) {
 55 |   const zodList =
 56 |     data instanceof z.ZodArray ? data : z.union([z.array(data), z.null()]);
 57 | 
 58 |   return getResSchema(
 59 |     zodPaginationParam.extend({
 60 |       total: z.number().max(10000),
 61 |       list: zodList,
 62 |     })
 63 |   );
 64 | }
 65 | 
 66 | /** 执行 zod 请求 */
 67 | export function zodRequest<T extends z.ZodTypeAny>(
 68 |   zodConfig: {
 69 |     schema: T;
 70 |     validate: boolean;
 71 |     enableMock: boolean;
 72 |   },
 73 |   requestConfig: AxiosRequestConfig
 74 | ): Promise<z.infer<T>> {
 75 |   const { schema, validate, enableMock } = zodConfig;
 76 |   if (enableMock && isLocal) {
 77 |     return Promise.resolve(generateMock(schema));
 78 |   } else {
 79 |     const host = window.location.pathname;
 80 |     const service = host.startsWith('/metadata/hotel')
 81 |       ? hotelRequest
 82 |       : rentalRequest;
 83 |     return service.request(requestConfig).then((res: z.infer<T>) => {
 84 |       if (validate) {
 85 |         // 走异步校验流程，不阻塞流程
 86 |         requestIdleCallback(() => {
 87 |           validateData(schema, res);
 88 |         });
 89 |       }
 90 |       return res;
 91 |     });
 92 |   }
 93 | }
 94 | 
 95 | /** 获取 zod 请求配置 */
 96 | export function getZodConfig<T extends z.ZodSchema>(
 97 |   validate: boolean,
 98 |   enableMock: boolean,
 99 |   schema: T
100 | ): { schema: T; validate: boolean; enableMock: boolean } {
101 |   return {
102 |     validate,
103 |     enableMock,
104 |     schema,
105 |   };
106 | }
107 | 
108 | /** 获取数组 zod 对象 */
109 | export function getArraySchema(data: z.ZodTypeAny) {
110 |   return z.union([z.array(data), z.null()]);
111 | }
