22 | service.interceptors.request.use(
23 |   (config: any) => {
24 |     return config;
25 |   },
26 |   (error: any) => {
27 |     return Promise.reject(error);
28 |   }
29 | );
30 | 
31 | service.interceptors.response.use(
32 |   (response) => {
33 |     trackRequest(response);
34 |     const { code, redirectUrl, errno } = response.data;
35 | 
36 |     if (code && code === 401) {
37 |       login();
38 |     }
39 | 
40 |     if (code && code !== 0) {
41 |       message.error(response.data.msg);
42 |       return Promise.reject(response.data);
43 |     }
44 |     return response.data;
45 |   },
46 |   (error) => {
47 |     if (error.response.status === 403) {
48 |       const baseUrl = error?.config?.baseURL || '';
49 |       const url = error?.config?.url || '';
50 |       const path = url.replace(baseUrl, '');
